@startuml

class User {
  + id : int
  + name : string
  + address : string
  + birthday : date
}

class BusinessOwner {
  + linkedInAccount : string
}

class PizzaRestaurant {
  + zipCode : string
  + address : string
  + phoneNumber : string
  + website : string
  + openingHours : string
}

class Pizza {
  + name : string
  + crustStructure : string
  + price : double
}

class Order {
  + id : int
  + orderDateAndTime : datetime
  + latestDeliveryTime : time
  + numberOfPeople : int
}

class EntertainmentOrder extends Order {
  + entertainmentType : string
  + duration : time
}

class Entertainer {
  + stageName : string
  + bio : string
  + pricePer30Minutes : double
}

class RestaurantEntertainmentAvailability {
  + day : string
}

BusinessOwner "1" -- "*" PizzaRestaurant : owns
PizzaRestaurant "1" -- "*" Pizza : offers
User "1" -- "1" BusinessOwner : is
User "1" -- "1" Entertainer : is
Order "0..*" EntertainmentOrder : includes
Entertainer "1" -- "1" Order : fulfills

@enduml

